consumerTryGetOwner:
    public bool TryGetOwner(ChunkId position, out LodNode owner)
    {
#if PERF_LOD || PERF_LOD_SCHEDULE
        using var measurement = Telemetry.Measure(TopologyLookup);
#endif
        // Voxtree's recent-address cache is mutable even on reads; serialize readers as well as updates.
        lock (_gate)
            for (var level = 0; level <= LodPolicy.MaxSupportedLevel; level++)
                if (_tree.TryGetLod(level, 0, position.X, position.Y, position.Z, out var resolution))
                {
                    owner = LodNode.Covering(resolution - 1, position);
                    return true;
                }
        owner = default;
        return false;
    }
